def regras_para_os_conjuntos(apps, schema_editor):
    Regra = apps.get_model("starchats", "RegraEnvio")
    Conjunto = apps.get_model("starchats", "ConjuntoEnvio")
    Ligacao = Conjunto._meta.get_field("regras").remote_field.through
    usados = set()
    for ligacao in Ligacao.objects.order_by("regraenvio_id", "conjuntoenvio_id"):
        regra = Regra.objects.get(pk=ligacao.regraenvio_id)
        if regra.pk in usados:
            original_id = regra.pk
            regra.pk = None
            regra.uuid = uuid.uuid4()
            regra.conjunto_id = ligacao.conjuntoenvio_id
            regra.save()
            Regra.objects.filter(pk=regra.pk).update(
                created_at=Regra.objects.get(pk=original_id).created_at
            )
        else:
            Regra.objects.filter(pk=regra.pk).update(
                conjunto_id=ligacao.conjuntoenvio_id
            )
            usados.add(regra.pk)


def conjuntos_para_muitos(apps, schema_editor):
    Regra = apps.get_model("starchats", "RegraEnvio")
    for regra in Regra.objects.exclude(conjunto_id=None):
        regra.conjunto.regras.add(regra)


